const watchCode = "import { render } from '@openinula/next';\r\nfunction UserInput() {\r\n  let count = 0;\r\n  function incrementCount() {\r\n    count = count + 1;\r\n  }\r\n\r\n  watch(() => {\r\n    alert('count changed:' + count);\r\n  });\r\n\r\n  return (\r\n    <>\r\n      <h1>{count}</h1>\r\n      <button onClick={incrementCount}>Add 1</button>\r\n    </>\r\n  );\r\n}\r\n\r\nrender(UserInput(), document.getElementById('app'));\r\n";

const treeCode = `import { render, createContext, useContext } from '@openinula/next';\r
\r
const TreeNode = ({ node, onToggle, idx = 0 }) => {\r
  let isExpanded = true;\r
  const handleToggle = () => {\r
    isExpanded = !isExpanded;\r
    onToggle(node.id, !isExpanded);\r
  };\r
  return (\r
    <div className="tree-node" style={{ marginLeft: '20px' }}>\r
      <div onClick={handleToggle} className="tree-node-content" style={{\r
        display: 'flex',\r
        alignItems: 'center',\r
        cursor: 'pointer',\r
        padding: '5px 0'\r
      }}>\r
        <if cond={node.children}>\r
          <span className={\`tree-node-toggle \${isExpanded ? 'expanded' : 'collapsed'}\`} style={{\r
            marginRight: '5px',\r
            transition: 'transform 0.3s',\r
            transform: isExpanded ? 'rotate(0deg)' : 'rotate(-90deg)'\r
          }}>\r
            ▼\r
          </span>\r
        </if>\r
        <else>\r
          <span className="tree-node-toggle" style={{ marginRight: '5px', visibility: 'hidden' }}>▼</span>\r
        </else>\r
        <span className="tree-node-name" style={{ fontFamily: 'Arial, sans-serif' }}>{idx + 1}. {node.name}</span>\r
      </div>\r
      <if cond={isExpanded}>\r
        <div className="tree-node-children" style={{\r
          borderLeft: '1px solid #ccc',\r
          marginLeft: '10px',\r
          paddingLeft: '10px'\r
        }}>\r
          <if cond={node.children}>\r
            <for each={node.children}>{(child, idx) => {\r
              return <TreeNode key={child.name} node={child} onToggle={onToggle} idx={idx} />\r
            }}</for>\r
          </if>\r
        </div>\r
      </if>\r
    </div>\r
  );\r
};\r
\r
const TreeView = ({ data }) => {\r
  let expandedNodes = [];\r
\r
  const handleToggle = (nodeId, isExpanded) => {\r
    if (isExpanded) {\r
      expandedNodes = [...expandedNodes, nodeId];\r
    } else {\r
      expandedNodes = expandedNodes.filter(id => id !== nodeId);\r
    }\r
  };\r
\r
  return (\r
    <div className="tree-view" style={{\r
      fontFamily: 'Arial, sans-serif',\r
      backgroundColor: '#f5f5f5',\r
      padding: '20px',\r
      borderRadius: '5px',\r
      boxShadow: '0 2px 5px rgba(0,0,0,0.1)'\r
    }}>\r
      <for each={data}>{node => <TreeNode key={node.id} node={node} onToggle={handleToggle} />}</for>\r
    </div>\r
  );\r
};\r
\r
function App() {\r
  const arr = [\r
    {\r
      name: "我的文档",\r
      children: [\r
        {\r
          name: "工作",\r
          children: [\r
            { name: "项目方案.docx" },\r
            { name: "会议记录.txt" },\r
            {\r
              name: "财务报表",\r
              children: [\r
                { name: "2023年第一季度.xlsx" },\r
                { name: "2023年第二季度.xlsx" },\r
                { name: "年度总结.pptx" }\r
              ]\r
            }\r
          ]\r
        },\r
        {\r
          name: "个人",\r
          children: [\r
            { name: "简历.pdf" },\r
            { name: "家庭照片.jpg" },\r
            {\r
              name: "旅行计划",\r
              children: [\r
                { name: "暑假海岛游.md" },\r
                { name: "冬季滑雪之旅.md" }\r
              ]\r
            }\r
          ]\r
        },\r
        { name: "待办事项清单.txt" }\r
      ]\r
    }\r
  ];\r
  return (\r
    <div className="app" style={{ maxWidth: '600px', margin: '0 auto' }}>\r
      <h1 className="app-title" style={{\r
        textAlign: 'center',\r
        color: '#333',\r
        marginBottom: '20px'\r
      }}>Tree View</h1>\r
      <TreeView data={arr} />\r
    </div>\r
  );\r
}\r
\r
render(\r
  App(),\r
  document.getElementById('app')\r
);\r
\r
\r
`;

const userInputCode = "import { render } from '@openinula/next';\nfunction UserInput() {\n  let count = 0;\n  function incrementCount() {\n    count = count + 1;\n  }\n\n  return (\n    <>\n      <h1>{count}</h1>\n      <button onClick={incrementCount}>Add 1</button>\n    </>\n  );\n}\n\nrender(UserInput(), document.getElementById('app'));\n";

